package org.mockito.internal.util;

import org.mockito.cglib.proxy.Callback;
import org.mockito.cglib.proxy.Factory;
import org.mockito.exceptions.misusing.NotAMockException;
import org.mockito.internal.InvocationNotifierHandler;
import org.mockito.internal.MockHandler;
import org.mockito.internal.MockHandlerInterface;
import org.mockito.internal.creation.MethodInterceptorFilter;
import org.mockito.internal.creation.MockSettingsImpl;
import org.mockito.internal.creation.jmock.ClassImposterizer;
import org.mockito.internal.util.reflection.LenientCopyTool;

import java.io.Serializable;

@SuppressWarnings("unchecked")
public class MockUtil {

    private final MockCreationValidator validator;

    public MockUtil(MockCreationValidator validator) {
        this.validator = validator;
    }

    public MockUtil() {
        this(new MockCreationValidator());
    }

    public <T> T createMock(Class<T> classToMock, MockSettingsImpl settings) {
        validator.validateType(classToMock);
        validator.validateExtraInterfaces(classToMock, settings.getExtraInterfaces());
        validator.validateMockedType(classToMock, settings.getSpiedInstance());

        settings.initiateMockName(classToMock);

        MethodInterceptorFilter filter = buildFilter(settings);
        Class<?>[] extraInterfaces = settings.getExtraInterfaces();

        Class<?>[] allTypes;
        if (settings.isSerializable()) {
            allTypes = (extraInterfaces == null)
                    ? new Class<?>[] {Serializable.class}
                    : new ArrayUtils().concat(extraInterfaces, Serializable.class);
        } else {
            allTypes = (extraInterfaces == null) ? new Class<?>[0] : extraInterfaces;
        }

        Object spied = settings.getSpiedInstance();

        T result = ClassImposterizer.INSTANCE.imposterise(filter, classToMock, allTypes);

        if (spied != null) {
            new LenientCopyTool().copyToMock(spied, result);
        }

        return result;
    }

    public <T> void resetMock(T mock) {
        MockHandlerInterface<T> previousHandler = getMockHandler(mock);
        MockHandler<T> replacementHandler = new MockHandler<T>(previousHandler);
        MethodInterceptorFilter replacementFilter = new MethodInterceptorFilter(
                replacementHandler,
                (MockSettingsImpl) org.mockito.Mockito.withSettings().defaultAnswer(org.mockito.Mockito.RETURNS_DEFAULTS));
        ((Factory) mock).setCallback(0, replacementFilter);
    }

    private <T> MethodInterceptorFilter buildFilter(MockSettingsImpl settings) {
        MockHandler<T> handler = new MockHandler<T>(settings);
        InvocationNotifierHandler<T> notifierHandler = new InvocationNotifierHandler<T>(handler, settings);
        return new MethodInterceptorFilter(notifierHandler, settings);
    }

    public <T> MockHandlerInterface<T> getMockHandler(T mock) {
        if (mock == null) {
            throw new NotAMockException("Argument should be a mock, but is null!");
        }

        if (!isMockitoMock(mock)) {
            throw new NotAMockException("Argument should be a mock, but is: " + mock.getClass());
        }
        return (MockHandlerInterface) getInterceptor(mock).getHandler();
    }

    private <T> boolean isMockitoMock(T mock) {
        return getInterceptor(mock) != null;
    }

    public boolean isMock(Object mock) {
        return (mock != null) && isMockitoMock(mock);
    }

    private <T> MethodInterceptorFilter getInterceptor(T mock) {
        if (false == (mock instanceof Factory)) {
            return null;
        }
        Factory factory = (Factory) mock;
        Callback callback = factory.getCallback(0);
        if (!(callback instanceof MethodInterceptorFilter)) {
            return null;
        }
        return (MethodInterceptorFilter) callback;
    }

    public MockName getMockName(Object mock) {
        return getMockHandler(mock).getMockSettings().getMockName();
    }
}
